// stylesheets imported for their side effect on web (Metro bundles them into the page)
declare module '*.css';
// MapLibre's CSP build (the phone's 3D view) has the same API as the package's main entry
declare module 'maplibre-gl/dist/maplibre-gl-csp.js' { import maplibre from 'maplibre-gl'; export default maplibre; }
// generated by metro.config.js: MapLibre's worker as a plain string
declare module '*/.maplibre-worker.js' { const src: string; export default src; }
